      const hydraulic_diameter_S = cell_diameter_um5_sum / cell_diameter_um4_sum;
      ring_data.push(cell_lumen_area_mean.toFixed(2), n_cells_in_this_treering.toFixed(0), vessel_density_n_mm2.toFixed(2), hydraulic_diameter_TZ.toFixed(2), hydraulic_diameter_S.toFixed(2));
